tape( 'the function cumulatively tests whether at least `k` elements in an ndarray are truthy (default, row-major)', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var out;
	var x;

	xbuf = [ 0.0, 1.0, 1.0, 0.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );

	out = emptyLike( x );

	actual = cusome( x, 2, out );
	expected = [ false, false, true, true ];

	t.strictEqual( actual, out, 'returns expected value' );
	t.strictEqual( isSameArray( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

